{
  "task_id": "gate_trojan_detection_tie_secen_001",
  "domain_id": "gate_trojan_detection",
  "title": "Gate-Level Trojan Detection: Peripheral Controller Analysis",
  "objective": "Analyze a flat gate-level netlist of a peripheral controller block to identify any anomalous drivers of control nets, and report structural findings in a JSON report.",
  "input_artifacts": [
    "inputs/controller_netlist.v",
    "inputs/cell_library.v",
    "inputs/design_brief.md",
    "inputs/testbench_regression.v"
  ],
  "submission_artifacts": [
    "submission/trojan_report.json"
  ],
  "expected_outputs": {
    "description": "A trojan_report.json under submission/ containing a verdict ('trojan_detected' or 'clean'), a list of suspect instance names drawn from controller_netlist.v, a rationale explaining the structural evidence, and (when applicable) the compromised net and its driving instance, plus optional orphaned/dangling logic instances.",
    "format": "JSON object with fields: verdict (string), suspect_instances (array of strings), rationale (string), and conditionally compromised_net (string), driver_instance (string), and optionally orphaned_logic (array of strings)."
  },
  "metrics": [
    {
      "name": "detection_rate",
      "direction": "maximize",
      "description": "Fraction of hard security requirements (correct verdict, correct compromised net, correct driver instance) satisfied by the submitted report, measured as a binary/graded pass rate across the acceptance criteria."
    },
    {
      "name": "false_positive_rate",
      "direction": "minimize",
      "description": "Fraction of suspect_instances or orphaned_logic entries listed by the submission that do not correspond to any real anomaly-relevant instance, normalized by total instances listed."
    },
    {
      "name": "inference_latency",
      "direction": "minimize",
      "description": "Wall-clock time in seconds for the grading pipeline to parse the netlist, cross-check the submitted report, and produce a verdict."
    },
    {
      "name": "structural_grounding_score",
      "direction": "maximize",
      "description": "Fraction of functional requirements satisfied (valid JSON schema, real instance-name references, required conditional fields present), independent of whether the security conclusion is correct."
    }
  ],
  "toolchain": [
    "yosys",
    "iverilog",
    "vvp"
  ],
  "notes": "Participants must not modify any file under inputs/. Only submission/trojan_report.json is graded."
}

// cell_library.v
//
// Minimal structural gate/cell library used by controller_netlist.v.
// All cells are purely combinational or simple synchronous-reset
// flip-flops with zero delay modeling (functional models only, no
// timing information).
//
// Module / port order conventions (must match instantiations exactly):
//   AND2(o, a, b)        - o = a & b
//   OR2 (o, a, b)        - o = a | b
//   INV (o, a)           - o = ~a
//   BUF (o, a)           - o = a
//   DFF (q, d, clk, rst) - synchronous-reset flop, active-high reset
//   TIEHI(o)             - o = 1'b1 (constant driver)
//   TIELO(o)             - o = 1'b0 (constant driver)
//   MUX2(o, a, b, sel)   - o = sel ? b : a

`timescale 1ns/1ps

module AND2 (
    output o,
    input  a,
    input  b
);
    assign o = a & b;
endmodule

module OR2 (
    output o,
    input  a,
    input  b
);
    assign o = a | b;
endmodule

module INV (
    output o,
    input  a
);
    assign o = ~a;
endmodule

module BUF (
    output o,
    input  a
);
    assign o = a;
endmodule

module DFF (
    output reg q,
    input      d,
    input      clk,
    input      rst
);
    always @(posedge clk) begin
        if (rst)
            q <= 1'b0;
        else
            q <= d;
    end
endmodule

module TIEHI (
    output o
);
    assign o = 1'b1;
endmodule

module TIELO (
    output o
);
    assign o = 1'b0;
endmodule

module MUX2 (
    output o,
    input  a,
    input  b,
    input  sel
);
    assign o = sel ? b : a;
endmodule

// controller_netlist.v
//
// Flat structural gate-level netlist for the 'controller' peripheral
// block. Built entirely from cells declared in cell_library.v.
//
// Ports:
//   clk            - system clock
//   rst            - synchronous active-high reset
//   access_grant   - access-control input
//   admin_override - access-control input
//   lock_bit       - access-control input
//   data_in[7:0]   - data input bus
//   data_out[7:0]  - data output bus
//   secure_enable  - observability output for the secure-mode enable net

`timescale 1ns/1ps

module controller (
    input        clk,
    input        rst,
    input        access_grant,
    input        admin_override,
    input        lock_bit,
    input  [7:0] data_in,
    output [7:0] data_out,
    output       secure_enable
);

    // -----------------------------------------------------------------
    // secure_enable drive
    // -----------------------------------------------------------------
    // secure_enable is driven directly by a constant-tie cell.
    TIEHI U_TIE_SECEN (
        .o (secure_enable)
    );

    // -----------------------------------------------------------------
    // Intended secure-enable computation cone
    // -----------------------------------------------------------------
    wire sec_and_out;
    wire sec_enable_calc;

    AND2 u_sec_and1 (
        .o (sec_and_out),
        .a (access_grant),
        .b (admin_override)
    );

    OR2 u_sec_or2 (
        .o (sec_enable_calc),
        .a (sec_and_out),
        .b (lock_bit)
    );
    // NOTE: sec_enable_calc has no further connections in this netlist;
    // it is not read by any other instance or output port.

    // -----------------------------------------------------------------
    // Unrelated functional datapath: data_in -> data_out
    // -----------------------------------------------------------------
    wire [7:0] data_reg_q;
    wire [7:0] data_muxed;
    wire       inv_lock_bit;

    INV u_inv_lock (
        .o (inv_lock_bit),
        .a (lock_bit)
    );

    MUX2 u_mux_bit0 (
        .o   (data_muxed[0]),
        .a   (data_in[0]),
        .b   (data_in[7]),
        .sel (inv_lock_bit)
    );

    BUF u_buf_bit1 (
        .o (data_muxed[1]),
        .a (data_in[1])
    );

    BUF u_buf_bit2 (
        .o (data_muxed[2]),
        .a (data_in[2])
    );

    BUF u_buf_bit3 (
        .o (data_muxed[3]),
        .a (data_in[3])
    );

    BUF u_buf_bit4 (
        .o (data_muxed[4]),
        .a (data_in[4])
    );

    BUF u_buf_bit5 (
        .o (data_muxed[5]),
        .a (data_in[5])
    );

    BUF u_buf_bit6 (
        .o (data_muxed[6]),
        .a (data_in[6])
    );

    BUF u_buf_bit7 (
        .o (data_muxed[7]),
        .a (data_in[7])
    );

    DFF u_dff_bit0 (
        .q   (data_reg_q[0]),
        .d   (data_muxed[0]),
        .clk (clk),
        .rst (rst)
    );

    DFF u_dff_bit1 (
        .q   (data_reg_q[1]),
        .d   (data_muxed[1]),
        .clk (clk),
        .rst (rst)
    );

    DFF u_dff_bit2 (
        .q   (data_reg_q[2]),
        .d   (data_muxed[2]),
        .clk (clk),
        .rst (rst)
    );

    DFF u_dff_bit3 (
        .q   (data_reg_q[3]),
        .d   (data_muxed[3]),
        .clk (clk),
        .rst (rst)
    );

    DFF u_dff_bit4 (
        .q   (data_reg_q[4]),
        .d   (data_muxed[4]),
        .clk (clk),
        .rst (rst)
    );

    DFF u_dff_bit5 (
        .q   (data_reg_q[5]),
        .d   (data_muxed[5]),
        .clk (clk),
        .rst (rst)
    );

    DFF u_dff_bit6 (
        .q   (data_reg_q[6]),
        .d   (data_muxed[6]),
        .clk (clk),
        .rst (rst)
    );

    DFF u_dff_bit7 (
        .q   (data_reg_q[7]),
        .d   (data_muxed[7]),
        .clk (clk),
        .rst (rst)
    );

    assign data_out = data_reg_q;

endmodule

// testbench_regression.v
//
// Self-contained regression testbench for the 'controller' module.
// Drives a handful of representative functional stimulus vectors and
// prints data_out / secure_enable for manual inspection.

`timescale 1ns/1ps

module testbench_regression;

    reg        clk;
    reg        rst;
    reg        access_grant;
    reg        admin_override;
    reg        lock_bit;
    reg  [7:0] data_in;
    wire [7:0] data_out;
    wire       secure_enable;

    controller dut (
        .clk            (clk),
        .rst            (rst),
        .access_grant   (access_grant),
        .admin_override (admin_override),
        .lock_bit       (lock_bit),
        .data_in        (data_in),
        .data_out       (data_out),
        .secure_enable  (secure_enable)
    );

    // 10ns clock period
    initial clk = 1'b0;
    always #5 clk = ~clk;

    initial begin
        $display("time\tacc\tadm\tlock\tdata_in\tdata_out\tsecure_enable");
        $monitor("%0t\t%b\t%b\t%b\t%h\t%h\t%b",
                  $time, access_grant, admin_override, lock_bit,
                  data_in, data_out, secure_enable);

        // Initialize and reset
        rst            = 1'b1;
        access_grant   = 1'b0;
        admin_override = 1'b0;
        lock_bit       = 1'b0;
        data_in        = 8'h00;
        @(posedge clk);
        @(posedge clk);
        rst = 1'b0;

        // Case 1: ordinary access, no override, no lock
        access_grant   = 1'b1;
        admin_override = 1'b0;
        lock_bit       = 1'b0;
        data_in        = 8'hA5;
        @(posedge clk);
        @(posedge clk);

        // Case 2: no access, admin override present but no grant
        access_grant   = 1'b0;
        admin_override = 1'b1;
        lock_bit       = 1'b0;
        data_in        = 8'h3C;
        @(posedge clk);
        @(posedge clk);

        // Case 3: full access and override together, unlocked
        access_grant   = 1'b1;
        admin_override = 1'b1;
        lock_bit       = 1'b0;
        data_in        = 8'hFF;
        @(posedge clk);
        @(posedge clk);

        // Case 4: neither access nor override, unlocked, idle data
        access_grant   = 1'b0;
        admin_override = 1'b0;
        lock_bit       = 1'b0;
        data_in        = 8'h00;
        @(posedge clk);
        @(posedge clk);

        // Case 5: brief reset pulse mid-stream, then resume ordinary traffic
        rst = 1'b1;
        @(posedge clk);
        rst = 1'b0;
        access_grant   = 1'b1;
        admin_override = 1'b0;
        lock_bit       = 1'b0;
        data_in        = 8'h5A;
        @(posedge clk);
        @(posedge clk);

        $display("Regression stimulus complete.");
        $finish;
    end

endmodule

{
  "verdict": "clean",
  "suspect_instances": [],
  "rationale": "No anomalies found; regression testbench passes and outputs match expected functional behavior."
}
